#!/usr/bin/env node
/**
 * Turns the SQL files generated by drizzle-kit into a plain TypeScript module.
 *
 * Why not the path drizzle documents for Expo, which imports the .sql files
 * directly? Because it needs babel-plugin-inline-import plus a Metro resolver
 * tweak, and D10 rejects NativeWind for exactly that reason: an extra step in
 * Metro and Babel is a failure point in a toolchain that cannot be debugged
 * locally, only through a fifteen-minute CI cycle.
 *
 * The generated module is plain TypeScript. It is type-checked like the rest of
 * the codebase, needs no bundler configuration at all, and carries no
 * dependency beyond what section 5 already lists. The shape it exports is the
 * one drizzle's migrate() expects.
 *
 * Run via `npm run migrations:bundle`. CI regenerates it and fails if the
 * result differs from what is committed.
 */

import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const MIGRATIONS_DIR = join(process.cwd(), 'src/core/db/migrations');
const OUTPUT = join(MIGRATIONS_DIR, 'bundle.generated.ts');

function key(idx) {
  return `m${String(idx).padStart(4, '0')}`;
}

function main() {
  const journal = JSON.parse(readFileSync(join(MIGRATIONS_DIR, 'meta/_journal.json'), 'utf8'));
  const entries = [...journal.entries].sort((a, b) => a.idx - b.idx);

  const known = new Set(
    readdirSync(MIGRATIONS_DIR).filter((name) => name.endsWith('.sql')),
  );

  for (const entry of entries) {
    if (!known.has(`${entry.tag}.sql`)) {
      throw new Error(`Journal lists ${entry.tag} but ${entry.tag}.sql is missing.`);
    }
  }
  if (known.size !== entries.length) {
    throw new Error(
      `${known.size} .sql files for ${entries.length} journal entries: an unlisted migration would never be applied.`,
    );
  }

  const migrations = entries
    .map((entry) => {
      const sql = readFileSync(join(MIGRATIONS_DIR, `${entry.tag}.sql`), 'utf8');
      return `  ${key(entry.idx)}: ${JSON.stringify(sql)},`;
    })
    .join('\n');

  const file = `// GENERATED by scripts/generate-migrations-bundle.mjs - do not edit by hand.
// Run: npm run migrations:bundle
//
// Shape expected by drizzle's migrate(). Migrations are never edited once
// delivered (D6/G2); this file only ever gains entries.

export interface MigrationJournalEntry {
  idx: number;
  version: string;
  /** Folder timestamp. This is what drizzle stores as created_at. */
  when: number;
  tag: string;
  breakpoints: boolean;
}

export interface MigrationBundle {
  journal: {
    version: string;
    dialect: string;
    entries: MigrationJournalEntry[];
  };
  migrations: Record<string, string>;
}

const bundle: MigrationBundle = {
  journal: ${JSON.stringify(journal, null, 2).replace(/\n/g, '\n  ')},
  migrations: {
${migrations}
  },
};

export default bundle;
`;

  writeFileSync(OUTPUT, file, 'utf8');
  console.log(`Wrote ${OUTPUT} (${entries.length} migration(s))`);
}

main();
